"use client";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Loader2 } from "lucide-react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import GoogleLoginButton from "@/app/(auth)/components/google-login-button";
import { toast } from "sonner";
import { useRegisterMutation } from "@/app/provider/api/authApi";
import Cookies from "js-cookie";
import PasswordField from "../component/password-field";
import { useState } from "react";
import { Checkbox } from "@/components/ui/checkbox";
import { useAnonMerge } from "@/hooks/use-anon-merge";
import { useRedirectIfAuthenticated } from "@/hooks/useRedirectIfAuthenticated";
import { AnonymousMergeDialog } from "@/components/anonymous-merge-dialog";

const registerSchema = z.object({
  displayName: z.string().min(2, "Display name must be at least 2 characters"),
  username: z.string().min(2, "Username must be at least 2 characters"),
  email: z.string().email("Invalid email address"),
  password: z.string().min(8, "Password must be at least 8 characters"),
  acceptedTerms: z.boolean().refine((v) => v === true, {
    message: "You must accept the Privacy Policy and Terms of Service.",
  }),
});

type FormValues = z.infer<typeof registerSchema>;

export default function RegisterContent() {
  useRedirectIfAuthenticated();
  const searchParams = useSearchParams();

  const from = searchParams.get("from") || null;
  const decodedFrom = from
    ? (() => { try { return decodeURIComponent(from); } catch { return from; } })()
    : null;
  const [registerMutation, { isLoading }] = useRegisterMutation();
  const [googleLoading, setGoogleLoading] = useState(false);
  const { pendingSessions, showDialog, isLoading: isMerging, handlePostAuth, confirmMerge, skipMerge } = useAnonMerge();

  const form = useForm<FormValues>({
    resolver: zodResolver(registerSchema),
    defaultValues: {
      email: "",
      password: "",
      displayName: "",
      username: "",
      acceptedTerms: false,
    },
    mode: "onChange",
  });

  const handleSubmit = async (values: FormValues) => {
    try {
      const res = await registerMutation(values as any).unwrap();
      if (from) localStorage.setItem("redirect_after_auth", from);
      Cookies.set("accessToken", res?.data?.accessToken, {
        expires: 7,
        sameSite: "strict",
        secure: process.env.NODE_ENV === "production",
      });
      Cookies.set("refreshToken", res?.data?.refreshToken, {
        expires: 7,
        sameSite: "strict",
        secure: process.env.NODE_ENV === "production",
      });
      toast.success("Account created successfully");

      const validFrom = decodedFrom && decodedFrom.startsWith("/") && !decodedFrom.startsWith("/auth")
        ? decodedFrom
        : null;

      // Always send new users to onboarding — they have no vibes yet
      const next = validFrom ? encodeURIComponent(validFrom) : encodeURIComponent("/events");
      await handlePostAuth(() => { window.location.href = `/onboarding/vibes?next=${next}`; });
    } catch (error: any) {
      const msg =
        error?.data?.error?.message ||
        error?.data?.message ||
        error?.response?.data?.message ||
        error?.message ||
        "Something went wrong. Please try again.";
      toast.error(msg);
    }
  };

  return (
    <div>
      {showDialog && (
        <AnonymousMergeDialog
          sessions={pendingSessions}
          isLoading={isMerging}
          onConfirm={(ids) => {
            const validFrom = decodedFrom && decodedFrom.startsWith("/") && !decodedFrom.startsWith("/auth");
            confirmMerge(ids, () => { window.location.href = validFrom ? decodedFrom! : "/events"; });
          }}
          onSkip={() => {
            const validFrom = decodedFrom && decodedFrom.startsWith("/") && !decodedFrom.startsWith("/auth");
            skipMerge(() => { window.location.href = validFrom ? decodedFrom! : "/events"; });
          }}
        />
      )}
      <GoogleLoginButton onLoadingChange={setGoogleLoading} />

      <div className="py-4 flex items-center gap-2 text-sm text-gray-500">
        <span className="h-px bg-gray-300 flex-1" />
        OR
        <span className="h-px bg-gray-300 flex-1" />
      </div>

      <Form {...form}>
        <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-4">
          <div className="flex flex-col gap-5">
            <FormField
              control={form.control}
              name="displayName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-sm font-medium text-gray-700">
                    Display Name
                  </FormLabel>
                  <FormControl>
                    <Input
                      placeholder="Enteryour display name"
                      className="h-11 rounded-lg border-gray-300 focus-visible:ring-[#5B1A57]"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="email"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-sm font-medium text-gray-700">
                    Email
                  </FormLabel>
                  <FormControl>
                    <Input
                      placeholder="Enter email"
                      className="h-11 rounded-lg border-gray-300 focus-visible:ring-[#5B1A57]"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="username"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-sm font-medium text-gray-700">
                    Username
                  </FormLabel>
                  <FormControl>
                    <Input
                      placeholder="Enter your username"
                      className="h-11 rounded-lg border-gray-300 focus-visible:ring-[#5B1A57]"
                      {...field}
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            <PasswordField
              name="password"
              label="Password"
              placeholder="Enter password"
              control={form.control}
            />

            <FormField
              control={form.control}
              name="acceptedTerms"
              render={({ field }) => (
                <FormItem>
                  <div className="flex items-start gap-3">
                    <FormControl>
                      <Checkbox
                        id="acceptedTerms"
                        checked={field.value}
                        onCheckedChange={field.onChange}
                        className="mt-0.5 shrink-0 border-gray-300 data-[state=checked]:bg-[#5B1A57] data-[state=checked]:border-[#5B1A57]"
                      />
                    </FormControl>
                    <p className="text-sm text-gray-600 leading-snug">
                      I have read and agree to the{" "}
                      <Link
                        href="/privacy"
                        target="_blank"
                        className="font-semibold text-[#5B1A57] underline underline-offset-2 hover:text-[#4a1446]"
                      >
                        Privacy Policy
                      </Link>
                      {" "}and{" "}
                      <Link
                        href="/terms"
                        target="_blank"
                        className="font-semibold text-[#5B1A57] underline underline-offset-2 hover:text-[#4a1446]"
                      >
                        Terms of Service
                      </Link>
                      .
                    </p>
                  </div>
                  <FormMessage className="ml-7" />
                </FormItem>
              )}
            />

            <Button
              type="submit"
              disabled={isLoading || googleLoading || isMerging || !form.watch("acceptedTerms")}
              className="w-full h-11 bg-[#5B1A57] hover:bg-[#4a1446] text-white rounded-lg font-medium disabled:opacity-50"
            >
              {isLoading ? (
                <span className="flex items-center gap-2">
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Creating account...
                </span>
              ) : isMerging ? (
                <span className="flex items-center gap-2">
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Saving your progress...
                </span>
              ) : (
                "Submit"
              )}
            </Button>
          </div>

          <p className="text-center text-sm font-medium text-gray-600 pt-1">
            Already have an account?{" "}
            <Link
              href="/auth/login"
              className="font-bold text-[#5B1A57] hover:underline underline-offset-2"
            >
              Login
            </Link>
          </p>
        </form>
      </Form>
    </div>
  );
}
